targets.query:
union(tables: [
  from(bucket: "infldb") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "raw"),
  from(bucket: "traffic-1m") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "1m"),
  from(bucket: "traffic-5m") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "5m"),
  from(bucket: "traffic-1h") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "1h"),
  from(bucket: "traffic-8h") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "8h"),
  from(bucket: "traffic-1d") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "1d"),
  from(bucket: "traffic-1w") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "1w"),
  from(bucket: "traffic-4w") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "4w"),
  from(bucket: "traffic-12w") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "12w"),
  from(bucket: "traffic-24w") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "24w"),
  from(bucket: "traffic-52w") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "52w"),
  from(bucket: "traffic-260w") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "260w"),
  from(bucket: "traffic-520w") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "network_interface") |> filter(fn: (r) => r._field == "statistics_out-octets") |> set(key: "tier", value: "520w")
])
  |> group(columns: ["hostname", "interface_name", "_field", "tier"])
  |> sort(columns: ["_time"])
  |> derivative(unit: 1s, nonNegative: true)
  |> map(fn: (r) => ({r with _value: r._value * 8.0}))

